					config,
					client,
					logger,
					harness: harnesses[servingId] ?? harness,
					harnessId: servingId,
					state,
					projectId: answer.projectId,
					taskId: answer.taskId,
					lease: {
					executionId: answer.executionId,
					epoch: answer.epoch,
